package com.immersio.scenarios.service;
import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.web.client.RestClient; import java.util.*;
@Service public class ScenarioLlmClient { private final String key; private final RestClient client; public ScenarioLlmClient(@Value("${openai.api-key:}") String key,@Value("${openai.base-url:https://api.openai.com/v1}") String base){this.key=key;client=RestClient.builder().baseUrl(base).build();} public String reply(String system,List<Map<String,String>> messages){if(key==null||key.isBlank()) return "Let's continue practicing. Could you tell me more?"; try {var body=new HashMap<String,Object>();body.put("model","gpt-4o-mini");body.put("messages",messages);var r=client.post().uri("/chat/completions").header("Authorization","Bearer "+key).body(body).retrieve().body(Map.class); var choices=(List<Map<String,Object>>)r.get("choices"); return String.valueOf(((Map<?,?>)choices.get(0).get("message")).get("content"));} catch(Exception e){return "Let's continue practicing. Could you tell me more?";} } }
